/*
 * A208761  Triangle of coefficients of polynomials u(n,x) jointly generated
 *          with A208762; see the Formula section.
 * https://oeis.org/A208761
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   a(n) is the nth element of the triangle of coefficients of * the
 *            polynomials u(n,x). The triangle is generated by the *
 *            recurrence * * T(1,1) = 1; * T(2,1) = 1, T(2,2) = 2; * T(n,k) =
 *            2*T(n-1,k) + T(n-1,k-1) - T(n-2,k) * + T(n-2,k-1) + 2*T(n-2,k-2)
 *            (for n ≥ 3, 1 ≤ k ≤ n). * * The sequence a(n) li...
 * Range:     u8 n <= 24, u16 n <= 55, u32 n <= 55, u64 n <= 55, u128 n <= 55,
 *            big any n
 * Helpers:   alloc_seq_row, free_seq_row
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include "../utils/alloc_seq_row.h"
#include "../utils/free_seq_row.h"

/* The cached triangle data. */
static idx_t          g_maxrow   = 0;   /* largest computed row index (≥0) */
static seq_t **       g_rows     = NULL;/* array of pointers to rows (1‑based) */
static idx_t *        g_start    = NULL;/* starting index of each row in a(n) */

/* Ensure that rows up to r are computed. */
static void ensure_rows(idx_t r)
{
    if (r <= g_maxrow) return;

    /* grow arrays for new rows */
    seq_t **new_rows  = (seq_t **)realloc(g_rows, (r + 1) * sizeof(seq_t *));
    idx_t  *new_start = (idx_t  *)realloc(g_start, (r + 1) * sizeof(idx_t));
    if (!new_rows || !new_start) abort();

    g_rows  = new_rows;
    g_start = new_start;

    /* compute rows that are missing */
    for (idx_t row = g_maxrow + 1; row <= r; ++row) {
        seq_t *curr = alloc_seq_row(row);
        if (!curr) abort();

        if (row == 1) {               /* T(1,1)=1 */
            curr[0] = (seq_t)1;
            g_start[1] = 1;
        } else if (row == 2) {        /* T(2,1)=1 , T(2,2)=2 */
            curr[0] = (seq_t)1;
            curr[1] = (seq_t)2;
            g_start[2] = g_start[1] + 1;      /* row 2 starts after row 1 */
        } else {
            /* recurrence for rows ≥3 */
            seq_t *prev1 = g_rows[row - 1];
            seq_t *prev2 = g_rows[row - 2];
            g_start[row] = g_start[row - 1] + (row - 1);

            for (idx_t k = 1; k <= row; ++k) {
                seq_t a = (k <= row - 1 ? prev1[k - 1] : (seq_t)0);          /* T(n-1,k) */
                seq_t b = (k > 1 && k - 1 <= row - 1 ? prev1[k - 2] : (seq_t)0);/* T(n-1,k-1) */
                seq_t c = (k <= row - 2 ? prev2[k - 1] : (seq_t)0);          /* T(n-2,k) */
                seq_t d = (k > 1 && k - 1 <= row - 2 ? prev2[k - 2] : (seq_t)0);/* T(n-2,k-1) */
                seq_t e = (k > 2 && k - 2 <= row - 2 ? prev2[k - 3] : (seq_t)0);/* T(n-2,k-2) */

                seq_t val = a * 2 + b + d + e * 2 - c;    /* recurrence */
                curr[k - 1] = val;
            }
        }
        g_rows[row] = curr;
    }
    g_maxrow = r;
}

seq_t a(idx_t n)
{
    if (n < 1)            /* 1‑based sequence: undefined for n<1 */
        return (seq_t)0;

    /* determine which row contains position n */
    idx_t required_row = 1;
    while ((required_row * (required_row + 1)) / 2 < n)
        ++required_row;

    /* build rows up to that row */
    ensure_rows(required_row);

    /* compute zero‑based offset within the row */
    idx_t start = g_start[required_row];      /* first index of this row */
    idx_t offset = n - start;                 /* 0‑based offset */

    return g_rows[required_row][offset];
}
